import { mkdtempSync, readdirSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { buildCompleteSummary, externalizeCompleteResult, externalizeProgressEvent, } from "./replayItemWriter.js";
let itemsDir;
beforeEach(() => {
    itemsDir = mkdtempSync(join(tmpdir(), "replay-items-"));
});
afterEach(() => {
    rmSync(itemsDir, { recursive: true, force: true });
});
function readItem(path) {
    return JSON.parse(readFileSync(path, "utf8"));
}
describe("externalizeProgressEvent", () => {
    const base = {
        completed: 1,
        total: 1,
        succeeded: 1,
        errored: 0,
        testRunId: "run-1",
    };
    it("writes a payload item file keyed by originalTraceId and slims the event", () => {
        const event = {
            ...base,
            item: {
                originalTraceId: "orig-1",
                replayTraceId: null,
                error: null,
                durationMs: 5,
                input: ["hi"],
                result: { ok: true },
            },
        };
        const out = externalizeProgressEvent(event, itemsDir, 0);
        expect(out.itemPath).toContain("orig-1.json");
        // The relayed event carries only the slim identity + a pointer, not the payload.
        expect(out.event.item).toEqual({
            originalTraceId: "orig-1",
            replayTraceId: null,
            error: null,
            durationMs: 5,
            itemPath: out.itemPath,
        });
        // The file carries the full payload; traceId is null during progress and
        // sourceTraceId mirrors originalTraceId as the deprecated alias.
        expect(readItem(out.itemPath)).toEqual({
            testRunId: "run-1",
            originalTraceId: "orig-1",
            sourceTraceId: "orig-1",
            traceId: null,
            replayTraceId: null,
            input: ["hi"],
            result: { ok: true },
            originalOutput: undefined,
            error: null,
            durationMs: 5,
            originalDurationMs: null,
            originalTokens: null,
            originalModel: null,
            dbBranchTimings: null,
            tokens: undefined,
            model: undefined,
            dbSnapshotRef: undefined,
        });
    });
    it("writes no file when the item carries no payload", () => {
        const event = {
            ...base,
            item: { originalTraceId: "orig-1", error: "boom", durationMs: 2 },
        };
        const out = externalizeProgressEvent(event, itemsDir, 0);
        expect(out.itemPath).toBeUndefined();
        expect(out.event).toBe(event);
        expect(readdirSync(itemsDir)).toHaveLength(0);
    });
    it("falls back to replayTraceId then progress-<index> for the file key", () => {
        const byReplay = externalizeProgressEvent({ ...base, item: { replayTraceId: "local-1", input: ["x"] } }, itemsDir, 0);
        expect(byReplay.itemPath).toContain("local-1.json");
        const byIndex = externalizeProgressEvent({ ...base, item: { input: ["y"] } }, itemsDir, 3);
        expect(byIndex.itemPath).toContain("progress-3.json");
    });
});
describe("externalizeCompleteResult", () => {
    it("modern lineage: keys the file by originalTraceId, keeps traceId as the server replay id", () => {
        const refs = externalizeCompleteResult({
            testRunId: "run-1",
            items: [
                {
                    originalTraceId: "orig-1",
                    traceId: "server-replay-1",
                    input: ["hi"],
                    error: null,
                    durationMs: 7,
                },
            ],
        }, itemsDir);
        expect(refs).toEqual([
            {
                originalTraceId: "orig-1",
                traceId: "server-replay-1",
                replayTraceId: null,
                itemPath: refs[0].itemPath,
                error: null,
                durationMs: 7,
            },
        ]);
        expect(refs[0].itemPath).toContain("orig-1.json");
        const file = readItem(refs[0].itemPath);
        expect(file.originalTraceId).toBe("orig-1");
        expect(file.sourceTraceId).toBe("orig-1");
        expect(file.traceId).toBe("server-replay-1");
        expect(file.replayTraceId).toBeNull();
    });
    // The complete write replaces the file the progress write made, so it has to
    // carry the same fields or the persisted payload silently loses them.
    it("keeps the original-trace metrics and branch timings on the final write", () => {
        const refs = externalizeCompleteResult({
            testRunId: "run-1",
            items: [
                {
                    originalTraceId: "orig-2",
                    traceId: "server-replay-2",
                    input: ["hi"],
                    error: null,
                    durationMs: 7,
                    originalDurationMs: 900,
                    originalTokens: { input: 1, output: 2, cached: 0, total: 3 },
                    originalModel: "claude-sonnet-4-5",
                    dbBranchTimings: { startedAt: "2026-08-08T00:00:00Z", totalMs: 42 },
                },
            ],
        }, itemsDir);
        const file = readItem(refs[0].itemPath);
        expect(file.durationMs).toBe(7);
        expect(file.originalDurationMs).toBe(900);
        expect(file.originalTokens).toEqual({
            input: 1,
            output: 2,
            cached: 0,
            total: 3,
        });
        expect(file.originalModel).toBe("claude-sonnet-4-5");
        expect(file.dbBranchTimings).toEqual({
            startedAt: "2026-08-08T00:00:00Z",
            totalMs: 42,
        });
    });
    it("legacy (no lineage): keys the file by the direct server traceId", () => {
        const refs = externalizeCompleteResult({ items: [{ traceId: "server-1", error: null }] }, itemsDir);
        expect(refs[0].originalTraceId).toBeNull();
        expect(refs[0].traceId).toBe("server-1");
        expect(refs[0].itemPath).toContain("server-1.json");
    });
    it("reads snake_case item fields", () => {
        const refs = externalizeCompleteResult({
            test_run_id: "run-1",
            items: [
                {
                    original_trace_id: "orig-1",
                    trace_id: "server-1",
                    original_output: { was: true },
                    duration_ms: 9,
                },
            ],
        }, itemsDir);
        expect(refs[0].originalTraceId).toBe("orig-1");
        expect(refs[0].durationMs).toBe(9);
        expect(readItem(refs[0].itemPath).originalOutput).toEqual({
            was: true,
        });
    });
    it("returns [] for a non-object or item-less result", () => {
        expect(externalizeCompleteResult(null, itemsDir)).toEqual([]);
        expect(externalizeCompleteResult({ items: "nope" }, itemsDir)).toEqual([]);
    });
    it("progress and complete writes for the same original trace land on ONE file", () => {
        externalizeProgressEvent({
            completed: 1,
            total: 1,
            succeeded: 1,
            errored: 0,
            item: { originalTraceId: "orig-1", input: ["hi"] },
        }, itemsDir, 0);
        externalizeCompleteResult({ items: [{ originalTraceId: "orig-1", traceId: "server-1" }] }, itemsDir);
        // One file per replay item, not two: the final write overwrites the live one.
        expect(readdirSync(itemsDir)).toEqual(["orig-1.json"]);
    });
});
describe("buildCompleteSummary", () => {
    it("projects run metadata and item count, accepting camelCase and snake_case", () => {
        expect(buildCompleteSummary({
            testRunId: "run-1",
            testRunUrl: "https://x/y",
            items: [{}, {}],
        })).toEqual({ testRunId: "run-1", testRunUrl: "https://x/y", itemCount: 2 });
        expect(buildCompleteSummary({
            test_run_id: "run-2",
            test_run_url: "https://a/b",
        })).toEqual({ testRunId: "run-2", testRunUrl: "https://a/b", itemCount: 0 });
    });
    it("returns {} for a non-object result", () => {
        expect(buildCompleteSummary("nope")).toEqual({});
    });
});
